// Accepts BOTH: POST JSON body (quick-log, Calendly feeder, My Day widget)
// and GET query params (one-click "log outcome" links in the daily digest).
const q = ($json.query && typeof $json.query === 'object') ? $json.query : {};
const hasBody = $json.body && typeof $json.body === 'object' && Object.keys($json.body).length > 0;
const b = hasBody ? $json.body : (Object.keys(q).length ? q : $json);
let metadata = null;
if (b.metadata && typeof b.metadata === 'object') metadata = b.metadata;
else if (b.note) metadata = { note: String(b.note).slice(0, 300), logged_via: 'digest_link' };
else if (!hasBody && Object.keys(q).length) metadata = { logged_via: 'digest_link' };
return [{ json: {
  account: b.account || null,
  contact: b.contact || null,
  source: b.source || null,
  event_type: b.event_type || null,
  campaign: b.utm_campaign || b.campaign || null,
  action_id: (b.action_id != null && b.action_id !== '' ? Number(b.action_id) : null),
  value: (b.value != null && b.value !== '' ? Number(b.value) : (hasBody ? null : 1)),
  occurred_at: b.occurred_at || new Date().toISOString(),
  metadata
} }];
